      SUBROUTINE DSOLE2CC     CALCULATES THE PARTIAL DERIVATIVES OF SECOND-ORDER MATRIX C     ELEMENTS WITH RESPECT TO PARAMETERS DESCRIBING A SOLENOIDC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM19.CIN'      INCLUDE 'T.CIN'C-------------------------------------------------------------------------------CC     LENGTH IS VARIEDC      IF (JV .EQ. 2) GO TO 10      TEMP = 0.5*KO*(SN + KL*CS)*LV      TV(1,16) = TEMP      TV(2,17) = TEMP      TV(3,18) = TEMP      TV(4,19) = TEMP      TEMP = KL*SN*LV      TV(1,17) = TEMP      TV(3,19) = TEMP      TEMP = - 0.5*KO*(CS - KL*SN)*LV      TV(1,18) = TEMP      TV(2,19) = TEMP      TV(4,17) = - TEMP      TV(3,16) = - TEMP      TEMP = - KL*CS*LV      TV(1,19) = TEMP      TV(3,17) = - TEMP      TEMP = 0.25*KO*(2.0*KO*CS - KO*KL*SN)*LV      TV(2,16) = TEMP      TV(4,18) = TEMP      TEMP = 0.25*KO*(2.0*KO*SN + KO*KL*SN)*LV      TV(2,18) = TEMP      TV(4,16) = - TEMP      GO TO 100CC     MAGNETIC FIELD IS VARIEDC   10 TEMP = 0.5*L*(SN + KL*CS)*UNITI(9)/PREF      TV(1,16) = TEMP      TV(2,17) = TEMP      TV(3,18) = TEMP      TV(4,19) = TEMP      TEMP = ( - SN/KO**2 + L*CS/KO + L**2*SN)*UNITI(9)/PREF      TV(1,17) = TEMP      TV(3,19) = TEMP      TEMP = - 0.5*L*(CS - KL*SN)*UNITI(9)/PREF      TV(1,18) = TEMP      TV(2,19) = TEMP      TV(4,17) = - TEMP      TV(3,16) = - TEMP      TEMP = ( - (1.0 - CS)/KO**2 + L*SN/KO - L**2*CS)*UNITI(9)/PREF      TV(1,19) = TEMP      TV(3,17) = - TEMP      TEMP = 0.25*(3.0*KL*CS - KL**2*SN + SN)*UNITI(9)/PREF      TV(2,16) = TEMP      TV(4,18) = TEMP      TEMP = 0.25*(3.0*KL*SN + KL**2*CS + 1.0 - CS)*UNITI(9)/PREF      TV(2,18) = TEMP      TV(4,16) = - TEMPC  100 RETURN      END